import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        long q = k;

        if (k == 0) {
            System.out.println(computePowerAlt(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(computePowerAlt(p, p));
            return;
        }

        int cycleCount = 1;
        while (q != 1) {
            q = (q * k) % p;
            cycleCount++;
        }
        System.out.println(computePowerAlt(p, (p - 1) / cycleCount));
    }

    static long computePowerAlt(long base, long exponent) {
        if (exponent == 0)
            return 1;
        long temp = computePowerAlt(base, exponent / 2);
        long result = (temp * temp) % MOD;
        if (exponent % 2 == 1) {
            result = (result * base) % MOD;
        }
        return result;
    }
}
